UPDATE T_NOTIFICATION
   SET  READ_YN = 'Y'
 WHERE 1=1
   AND USER_ID = #{userId}
   AND READ_YN = 'N'

   AND ID = #{id}

mapper.select:
SELECT  COUNT(*)
  FROM T_PREDICT_VOTE V
  JOIN T_PREDICT_ITEM I ON I.ID = V.ITEM_ID
 WHERE 1=1
   AND V.USER_ID    = #{userId}
   AND I.TRADE_DATE = #{tradeDate}

SELECT USER_ID FROM (
    SELECT A.USER_ID FROM T_ATTENDANCE A WHERE A.DAY BETWEEN #{from} AND #{to}
    UNION
    SELECT P.USER_ID FROM T_NEWS_QUIZ_PLAY P WHERE P.QUIZ_DATE BETWEEN #{from} AND #{to}
    UNION
    SELECT V.USER_ID FROM T_PREDICT_VOTE V JOIN T_PREDICT_ITEM I ON I.ID = V.ITEM_ID WHERE I.TRADE_DATE BETWEEN #{from} AND #{to}
    UNION
    SELECT T.USER_ID FROM T_MOCK_TRADE T WHERE T.INS_DAY >= (#{from}::TIMESTAMP AT TIME ZONE 'Asia/Seoul') AND T.INS_DAY < ((#{to}::DATE + 1)::TIMESTAMP AT TIME ZONE 'Asia/Seoul')
) X
JOIN T_USER U ON U.ID = X.USER_ID AND U.DEL_DAY IS NULL
ORDER BY USER_ID
LIMIT  #{limit}
